package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_unescape_TriageGen0Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }





























    @Test
    public void testUnescape_ComplexEdgeCases() {
        // Test case where & is followed by something that isn't an entity but has a semicolon later
        // e.g., "&notanentity;" -> if entityValue is -1, it returns original string
        assertEquals("&notanentity;", entities.unescape("&notanentity;"));

        // Test case where & is followed by another & before a semicolon
        // &abc&def; -> first & is treated as literal because next & is before ;
        assertEquals("&abc&def;", entities.unescape("&abc&def;"));
    }


}

